import{z as o,x as m,o as l,c as p,q as A,j as s,D as t,d as e,s as n,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"潜空间与 VAE","description":"","frontmatter":{"title":"潜空间与 VAE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/latent-vae.md","filePath":"llm/latent-vae.md","lastUpdated":1791413859000}'),B={name:"llm/latent-vae.md"};function D(d,a,h,f,c,V){const i=m("Mermaid");return l(),p("div",null,[a[2]||(a[2]=A('<h1 id="潜空间与-vae" tabindex="-1">潜空间与 VAE <a class="header-anchor" href="#潜空间与-vae" aria-label="Permalink to &quot;潜空间与 VAE&quot;">​</a></h1><div class="epigraph"><p>先把图压进低维连续潜变量，再在潜空间里扩散或流。像素解码器负责纹理，生成器不必每步在 RGB 上跑。</p><footer>—— Kingma, Welling, VAE；Rombach 等 Latent Diffusion / Stable Diffusion</footer></div><p><a href="/llm/flow-matching">上一课</a>与 <a href="/llm/ddpm">DDPM</a> 都可以在数据空间做。缺口是算力：高分辨率 RGB 上每步 U-Net 不可扩展。Rombach 等人先训感知压缩的 VAE，再在 \\(z\\) 上做扩散。后课 CFG 默认生成器已经活在这个 \\(z\\) 上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>像素扩散的空间是 \\(H\\times W\\times 3\\)，每一步去噪都要让 U-Net 在这个大空间上过一遍。Rombach 等人把生成拆成两段账。感知压缩丢掉人眼不可分的高频细节：VAE 用感知重构损失加 patch 级对抗目标训练（与 <a href="/llm/vqgan">VQGAN</a> 的解码器同一配方，只是不量化），下采样 \\(f=8\\) 时把 \\(H\\times W\\times 3\\) 压成 \\((H/8)\\times(W/8)\\times 4\\)，512 方图约 48 倍缩减。语义压缩是学布局、物体、属性的组合规律——这才是生成模型该花容量的地方。像素扩散把两段压给同一个 U-Net：绝大多数梯度与步数花在不可感知的纹理上；两阶段让生成器只做语义段，训练与采样都在缩小 48 倍的空间上算，这才有分辨率与批量的扩展余地。VAE 编码器 \\(E\\) 给出 \\(z=E(x)\\)，解码器 \\(D\\) 重构 \\(\\hat x=D(z)\\)。与 <a href="/llm/vq-vae">VQ-VAE</a> / <a href="/llm/vqgan">VQGAN</a> 不同：这里的 \\(z\\) 常保持连续（对角高斯后验），不量化成词表。LDM 的关键是：感知损失 + 对抗让 \\(D(z)\\) 够锐，于是潜空间里的生成误差在像素上仍可看。</p><p>连续 \\(z\\) 不能当 softmax 词表，这正是<a href="/llm/continuous-vs-discrete-vision-tokens">连续对离散</a> 在生成侧的选择：扩散/流走连续潜变量；AR 走离散码。</p><p><span class="marginnote">下采样倍数（如 8×）决定 \\(z\\) 的空间格。压太狠，文字与布局先坏——文档生成与理解侧 squish 是同一类信息损失。</span></p><p><span class="marginnote">数字实例：\\(512\\times512\\times3\\) 的图有 786,432 个数；\\(f=8\\) 后的 \\(64\\times64\\times4\\) 潜变量只有 16,384 个数——48 倍缩减。扩散每一步、每一批都在这 1/48 的空间上算 U-Net，这就是同一张卡能上更大分辨率和批量的直接来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两阶段：先冻好 VAE，再只训潜空间的 \\(\\epsilon_\\theta(z_t,t,c)\\) 或速度场。冻的理由：VAE 若继续更新，生成器面对的是一个移动的靶——潜分布漂，噪声水平跟着漂，日程与超参永无稳定参照；先钉住 \\(z\\) 的分布，生成端才可复现。</p><p>归一化是这层参照的一部分。VAE 潜变量的每维经验方差常远小于 \\(1\\)：编码器把能量压进少数维，而日程、\\(\\sigma_{\\max}\\) 等采样超参按单位方差数据设计。LDM 先在数据集上统计编码后潜变量的标准差 \\(\\hat\\sigma\\)，把 \\(z\\) 除以它再训生成器，解码前乘回（Stable Diffusion 的 \\(0.18215\\) 即此数）。为什么必须做：方差小一个量级等于整条信噪比曲线整体左移，前几步就把信号淹掉，网络大部分步花在近纯噪声上；归一化让像素侧调好的日程假设直接迁移。不这么做会错在哪：同一套日程训出发散或欠曝的生成器，而你以为是日程、网络或数据的问题，往错的方向调。</p><p><span class="marginnote">直觉类比：\\(0.18215\\) 这个数像一道汇率。VAE 把「价格」都按自己的小币种记账（方差远小于 1），而扩散日程是按「单位方差」这个标准币种设计的。除以 \\(\\hat\\sigma\\) 就是把小币种统一换算成标准币，解码前乘回是换回来——不换汇，日程表上所有数值全都对不上号。</span></p><p>条件 \\(c\\) 可以是文本塔（常与 <a href="/llm/clip">CLIP</a> 文本编码器相关，但那是条件接口，不是 LLaVA 那种视觉前缀）。验收：重构 FID 与生成 FID 分开——前者钉 \\(D\\) 的天花板，后者钉生成器；盯文字可读性，不要只报风景 FID：潜空间误差对高频文字的放大在风景图上看不见，OCR 样张过一遍才作数。</p>',13)),(l(),s(r,null,{default:t(()=>[n(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%83%8F%E7%B4%A0%22%5D%20--%3E%20E%5B%22VAE%20%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20E%20--%3E%20Z%5B%22%E8%BF%9E%E7%BB%AD%E6%BD%9C%E5%8F%98%E9%87%8F%20z%22%5D%0A%20%20Z%20--%3E%20DIFF%5B%22%E6%89%A9%E6%95%A3%E6%88%96%E6%B5%81%22%5D%0A%20%20DIFF%20--%3E%20D%5B%22VAE%20%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A%20%20D%20--%3E%20XHAT%5B%22%E5%83%8F%E7%B4%A0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("生成器学的是 \\(p(z)\\)，细节纹理由 \\(D\\) 的先验补全——与 VQGAN 解码器「编造高频」同类。因此潜空间 FID 好看不等于 OCR 忠实：解码器可以把糊的笔画补成合理的字，也可以把对的字补糊，两个方向的错误都发生在生成器看不见的那一段。归一化还影响引导：CFG 类引导以潜变量为单位外推，换一个没归一的潜空间，同一引导系数的等效力度完全不同，超参不可跨空间迁移。理解用的 "),E("a",{href:"/llm/vit-as-encoder"},"ViT"),e(" patch 与生成用的 \\(z\\) 格，分辨率协议往往不同，统一模型必须显式对齐或分塔，见后课 Janus。")],-1)),(l(),s(r,null,{default:t(()=>[n(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E7%94%9F%E6%88%90%E5%99%A8%E5%9C%A8%E6%BD%9C%E7%A9%BA%E9%97%B4%E9%87%87%E6%A0%B7%20z%22%5D%20--%3E%20D%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%20D%22%5D%0A%20%20D%20--%3E%20Q1%5B%22%E9%AB%98%E9%A2%91%E7%BA%B9%E7%90%86%3AD%20%E7%9A%84%E5%85%88%E9%AA%8C%E7%BC%96%E9%80%A0%22%5D%0A%20%20D%20--%3E%20Q2%5B%22%E7%AC%94%E7%94%BB%E7%BB%86%E8%8A%82%3A%E5%8F%AF%E8%83%BD%E8%A1%A5%E5%AF%B9%E4%B9%9F%E5%8F%AF%E8%83%BD%E8%A1%A5%E7%B3%8A%22%5D%0A%20%20Q1%20--%3E%20V%5B%22%E7%94%9F%E6%88%90%20FID%20%E5%A5%BD%E7%9C%8B%22%5D%0A%20%20Q2%20--%3E%20W%5B%22OCR%20%E6%A0%B7%E5%BC%A0%E9%9C%B2%E9%A6%85%22%5D%0A%20%20V%20--%3E%20R%5B%22%E7%BB%93%E8%AE%BA%3AFID%20%E4%B8%8E%20OCR%20%E5%BF%A0%E5%AE%9E%E5%88%86%E5%BC%80%E9%AA%8C%E6%94%B6%22%5D%0A%20%20W%20--%3E%20R%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">常见误区：初学者容易把「重构清晰、FID 很低」当成「模型会写字」。实际上文字的可读性主要由解码器先验兜底——生成器给出的 \\(z\\) 哪怕把笔画压糊了，解码器也能「脑补」成一个像样的字，只是未必是你要求的那个字。验证文字能力只能靠 OCR 抽查样张，不能只看整体指标。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>VAE 重构天花板仍在：生成器再好也回不到 \\(D(z)\\) 之外的细节。下一课在已有条件扩散上加无分类器引导，不改这个潜空间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>潜空间 VAE 把扩散/流从像素挪到连续 \\(z\\)；感知压缩与语义压缩分段记账。</li><li>潜变量方差先归一（scale factor），日程与引导超参才有稳定参照。</li><li>连续 \\(z\\) 服务采样，不是 AR 词表。</li><li>重构天花板限制文字与布局。</li><li>出处：Kingma &amp; Welling VAE；Rombach 等 LDM。</li></ul>',5))])}const F=o(B,[["render",D]]);export{_ as __pageData,F as default};
